command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="24bb8722c06b302f6a6b9c00aad34293a38be0d0";$candidate="74550ff2c67633371d1c3ad2e266c32a7e7c8ed1";$branch="work/unc-network-copy-move-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "UNC docs FAST fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before UNC docs FAST"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "UNC docs candidate moved"}
$temp=Join-Path $env:RUNNER_TEMP ("fly-unc-docs-fast-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
 & git worktree add --detach $temp $candidate
 if($LASTEXITCODE -ne 0){throw "UNC docs worktree add failed"}
 Set-Location -LiteralPath $temp
 & git diff --check ($main+"..."+$candidate)
 if($LASTEXITCODE -ne 0){throw "UNC docs diff check failed"}
 & python -X utf8 tools\winui\run_checks.py fast --before $main --head $candidate
 if($LASTEXITCODE -ne 0){throw "UNC docs FAST failed"}
 Write-Host "UNC_COPY_MOVE_DOCS_DIFF_CHECK=PASS"
 Write-Host "UNC_COPY_MOVE_DOCS_FAST=PASS"
 Write-Host "UNC_COPY_MOVE_REUSED_FINAL_GUI_RUN=37556148841"
 Write-Host "UNC_COPY_MOVE_REUSED_M22_DEBUG_RUN=37553534009"
 Write-Host "UNC_COPY_MOVE_REUSED_M22_RELEASE_RUN=37553699165"
 Write-Host "UNC_COPY_MOVE_PHYSICAL_SMB=NOT_RUN_NO_OWNED_SHARE"
}finally{
 Set-Location -LiteralPath $repo
 if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
 & git worktree prune
}
